function bloque(categoria: Categoria, subcategoria: string, texto: string): Servicio[] {
  const filas = texto
    .trim()
    .split('\n')
    .map((linea) => linea.trim())
    .filter(Boolean)
    .map((linea) => {
      const partes = linea.split(' | ')
      if (partes.length !== 8 && partes.length !== 7) throw new Error(`Ficha incompleta: ${linea}`)
      const [nombre, resumen, problema, solucion, beneficios, sexto, septimo, octavo] = partes
      const entregables = partes.length === 8 ? sexto : beneficios
      const herramientas = partes.length === 8 ? septimo : sexto
      const etiquetas = partes.length === 8 ? octavo : septimo
      const par = beneficios.split('; ')
      if (par.length !== 2) throw new Error(`Beneficios: ${nombre}`)
      return {
        nombre,
        resumen,
        problema,
        solucion,
        beneficios: [par[0], par[1]] as [string, string],
        entregables: entregables.split('; ').map((item) => item.trim()).filter(Boolean),
        herramientas: herramientas.split('; '),
        etiquetas: etiquetas.split('; ') as Etiqueta[],
      }
    })
  return armar(categoria, subcategoria, filas)
}

