const etiquetasValidas = new Set(['Desarrollo', 'Marketing', 'Datos', 'Automatización', 'Consultoría', 'Legal', 'Soporte', 'Freelance'])
const ids = new Set<string>()
for (const servicio of servicios) {
  if (ids.has(servicio.id)) throw new Error(`Servicio duplicado: ${servicio.id}`)
  for (const etiqueta of servicio.etiquetas) {
    if (!etiquetasValidas.has(etiqueta)) throw new Error(`Etiqueta desconocida en ${servicio.nombre}: ${etiqueta}`)
  }
  ids.add(servicio.id)
  const ruta = `${servicio.categoriaSlug}/${servicio.slug}`
  const repetida = servicios.find((otro) => otro !== servicio && `${otro.categoriaSlug}/${otro.slug}` === ruta)
  if (repetida) throw new Error(`Ruta duplicada: ${ruta}`)
}

export function categoriaPorSlug(valor: string) {
  return categorias.find((categoria) => categoria.slug === valor)
}

export function servicioPorRuta(categoriaSlug: string, servicioSlug: string) {
  return servicios.find((servicio) => servicio.categoriaSlug === categoriaSlug && servicio.slug === servicioSlug)
}

export function serviciosDeCategoria(categoriaSlug: string) {
  return servicios.filter((servicio) => servicio.categoriaSlug === categoriaSlug)
}
